export const CreateObjectView = observer(({ model }: { model: CreateObjectModel }) => {
 return (
   <div data-testid="CreateObjectView">
     <label htmlFor="selectedAssetId">Asset:</label>
     <select id="selectedAssetId" value={model.selectedAsset} onChange={() => {
       if (model.selectedAsset && model.availableAssets.find(({ value: assetValue }) => assetValue === model.selectedAsset)) {
         model.createObject(model.selectedAsset).then(() => model.setSelectedAsset(model.selectedAsset));
       }
     }}>
       {model.availableAssets.map(({ value, label }) => (
         <option key={value} value={value}>
           {label}
